// How each function on a pick works and when you'd use it, shown under "How to use it" on the pick's card.
// HOW has one entry per kind of function: its name, how it works, an everyday example and, where lab.js has a working
// model of it, the model's name ("demo"), which becomes a link to #lab-<demo>.
// PICK_HOW lists the functions each pick has, keyed by the pick's key in PICKS: [key in HOW, a note about this watch].
// Sub-dial positions, scales and bezels were read off the makers' photos and spec pages in November 2026.
const HOW = {
"chrono":{"n":"Stopwatch (chronograph)",
  "how":"The top button starts and stops the long centre seconds hand, and the bottom button sends it back to zero once it has stopped. The small dials count the minutes, and on some watches the hours, that have gone by. The watch keeps telling the time throughout: its own seconds tick round one of the small dials, which is why the long hand sits still at 12 until you start it.",
  "eg":"Start it when the pasta goes in, the parking meter starts or a meeting begins, and read off how long it has been. Stop it for a pause and press the top button again to carry on from there. Don't press the buttons underwater.",
  "demo":"stopwatch"},
"tachy":{"n":"Tachymeter (speed scale)",
  "how":"A scale that turns a time into a speed. Start the stopwatch as you pass one marker and stop it when you have covered exactly one mile or one kilometre: the long seconds hand now points at your average speed per hour. It works for times from about 7 seconds up to a minute.",
  "eg":"On a motorway, start at one mile marker and stop at the next. If that took 40 seconds the hand points at 90, so you averaged 90 mph. It counts anything else per hour too: a job that takes 30 seconds reads 120, so you'd get through 120 of them in an hour.",
  "demo":"tachymeter"},
"telemeter":{"n":"Telemeter (distance scale)",
  "how":"A scale that turns the gap between seeing something and hearing it into a distance, using the speed of sound, which covers about a kilometre every three seconds. Start the stopwatch when you see the flash and stop it when you hear the bang: the long seconds hand points at how far away it was.",
  "eg":"Lightning flashes and you start it; the thunder arrives 9 seconds later and you stop it. The hand points at 3, so the strike was about 3 km away. Time the next one: a smaller number means the storm is coming towards you.",
  "demo":"telemeter"},
"flyback":{"n":"Flyback",
  "how":"On an ordinary chronograph, starting a new timing takes three presses: stop, reset, start. On a flyback, one press of the bottom button while the stopwatch is running sends the hand back to zero and it starts again at once.",
  "eg":"Timing things back to back without losing a second: each lap of a run, each interval of a workout, each leg of a route. Pilots used it to start timing a new heading at the moment they turned.",
  "demo":"stopwatch-flyback"},
"sliderule":{"n":"Slide rule",
  "how":"A times table you set yourself. Two rings carry the same numbers: the outer one turns with the bezel and the inner one stays put. Put a number on one beside a number on the other and you have told the watch one fact, such as \"10 euros is 11 dollars\". Every other pair around the dial now follows that fact, so 50 sits beside 55 and you read the answer off with no sum to do. The rings only run from 10 to 100, so 12 also stands for 1.2 or 120: you judge which by common sense.",
  "eg":"Changing money at 1.10 dollars to the euro: turn the bezel until 11 on the outer ring sits beside the red 10 on the inner ring, and 50 euros on the inner ring is beside 55 dollars on the outer. Driving at 120 km/h, which is 120 km every 60 minutes: put 12, standing for 120, beside the inner ring's 60, which has the MPH arrow. Minutes are now on the inner ring and distance on the outer, so 45 minutes is beside 90 km. The red NAUT, STAT and KM marks turn nautical miles, miles and kilometres into each other.",
  "demo":"sliderule"},
"marker":{"n":"Turning bezel with a marker",
  "how":"Turn the bezel so its mark sits at the minute hand, or at the point the minute hand will reach when time is up. It stays there as a reminder, with no button to press and nothing to reset.",
  "eg":"You pay for 40 minutes of parking: put the mark 40 minutes ahead of the minute hand, and you're due back when the hand reaches it. Or put the mark on the minute hand when the roast goes in, to see later how long it has had."},
"timing":{"n":"Timing bezel",
  "how":"Turn the bezel so its triangle lines up with the minute hand. From then on the minute hand points at the number of minutes that have passed, up to an hour.",
  "eg":"Set it as the pizza goes in or as you leave the car, and read the minutes gone straight off the bezel. That leaves the stopwatch free to time something else.",
  "demo":"bezel"},
"dive":{"n":"Dive bezel",
  "how":"Turn the bezel so its triangle lines up with the minute hand. From then on the minute hand points at the number of minutes that have passed, up to an hour. It only turns anticlockwise, so a knock can only make it show more time gone, never less: for a diver, that errs on the side of coming up early.",
  "eg":"Underwater it tracks time against the air supply. On land it's the easiest timer there is, with no buttons: set it when the washing goes on, when you pay for 40 minutes of parking, or when the barbecue is lit.",
  "demo":"bezel"},
"innerbezel":{"n":"Inner turning bezel",
  "how":"The minute ring sits under the glass, where it can't be knocked, and a second crown turns it. Line its triangle up with the minute hand, and the minute hand then points at the number of minutes that have passed, up to an hour.",
  "eg":"The same everyday timer as a dive bezel: a parking meter, a train to catch, something in the oven. Because the ring is sealed inside, it can't shift by accident once it's set.",
  "demo":"bezel"},
"countdown":{"n":"Countdown bezel",
  "how":"The numbers run backwards. Turn the bezel so the number of minutes you have sits at the minute hand: the hand then counts down, and when it reaches the triangle the time is up.",
  "eg":"The train leaves in 25 minutes: put 25 at the minute hand. A glance at any point shows how many minutes are left, with no sums.",
  "demo":"bezel-countdown"},
"compass":{"n":"Compass bezel",
  "how":"Hold the watch flat and point the hour hand at the sun. In the northern hemisphere, south lies halfway between the hour hand and 12 o'clock (use 1 o'clock in summer time). Turn the bezel so S sits there, and the other letters show north, east and west.",
  "eg":"On a walk with no phone signal, a quick check that you're still heading roughly the right way. It's a rough guide for a clear day, not a substitute for a real compass."},
"gmt":{"n":"Second time zone (GMT)",
  "how":"A fourth hand goes round once every 24 hours and points at the 24-hour numbers on the bezel. The ordinary hour hand can be moved on its own in one-hour jumps, forwards or backwards, without stopping the watch.",
  "eg":"Leave the 24-hour hand on home time. When you land, pull the crown out one step and jump the hour hand to local time; the date goes with it. A glance at the 24-hour hand then tells you whether it's a sensible hour to phone home: if it points at 22, it's 10pm there.",
  "demo":"gmt"},
"gmtcaller":{"n":"Second time zone, caller kind (GMT)",
  "how":"A fourth hand goes round once every 24 hours and points at the 24-hour scale. On this kind it is the 24-hour hand that you set on its own, in one-hour jumps, while the hour and minute hands keep running; the ordinary hour hand doesn't jump.",
  "eg":"Set the 24-hour hand to home or the office once and leave the main hands on local time. When you travel and want local time on the main hands, set them the ordinary way, then move the date and the 24-hour hand back to where they were. The working model on this page shows the other kind, so there's no Try it link here."},
"hours12":{"n":"12-hour bezel (second time zone)",
  "how":"The bezel carries a second set of hour numbers and turns both ways. Turn it until the hour it is somewhere else sits at the hour hand. From then on the hour hand shows the time there on the bezel and the time where you are on the dial. The minutes are the same in both.",
  "eg":"It's 3 o'clock at home and 8 o'clock in London: turn the bezel until its 8 sits at the hour hand, and leave it. Later, when the hour hand has moved on to the bezel's 11, it's 11 in London. It can't tell morning from evening, so you need to know that yourself."},
"jumphour":{"n":"Hour hand that jumps",
  "how":"Pull the crown out one step and the hour hand moves in one-hour jumps, forwards or backwards, while the minutes and seconds keep running. The date changes with it each time the hand passes midnight.",
  "eg":"Landing in a new time zone or changing the clocks takes a few seconds and the watch stays right to the second. It's also how the date is set: take the hour hand twice round the dial for each day."},
"reserve":{"n":"Power reserve display",
  "how":"A small hand on the dial works like a fuel gauge for the mainspring. It shows full when the watch is fully wound and drops towards empty over about three days off the wrist.",
  "eg":"Before leaving the watch in a drawer for the weekend, a glance says whether it will still be running on Monday. If it's low, wearing it or winding the crown tops it up."},
"pointer":{"n":"Pointer date",
  "how":"Instead of a small window, a centre hand points at the date on a ring numbered 1 to 31 around the edge of the dial.",
  "eg":"It's easier to read at a glance than a window, and it shows how far through the month you are. After a month with fewer than 31 days, move it on to the 1st by hand."},
"ringdate":{"n":"Ring date",
  "how":"The dates 1 to 31 run round the edge of the dial, and two red marks sit either side of today's.",
  "eg":"It reads at a glance without a magnified window. The crown sets it backwards as well as forwards, so going one day too far doesn't mean winding through a whole month."},
"date":{"n":"Date",
  "how":"A numbered disc under the dial clicks over once a day at about midnight. The watch treats every month as 31 days long, so after a shorter month it needs moving on by hand, five times a year. On most watches you pull the crown out one step (unscrewing it first if it screws down) and turn it.",
  "eg":"On the morning of 1 May the watch says 31: move it on one day. Don't change the date when the hands show between about 9pm and 3am, when the mechanism is already in gear: on many watches forcing it then does damage. If in doubt, move the hands to 6 o'clock first."},
"daydate":{"n":"Day and date",
  "how":"Two discs show the day of the week and the date, and both click over at about midnight. With the crown pulled out one step, turning it one way changes the date and the other way changes the day.",
  "eg":"After a month with fewer than 31 days, move the date on by hand. As with any date, don't change either one when the hands show between about 9pm and 3am: move the hands to 6 o'clock first."},
};
